import 'dart:convert';

import '../models/account_preferences.dart';
import '../models/chest.dart';
import '../models/egg_altar.dart';
import '../models/shop_item.dart';
import '../models/profile_portrait.dart';
import '../models/account_title.dart';
import '../models/music_track.dart';
import '../models/adventure.dart';
import '../models/pet.dart';
import '../models/house.dart';
import 'canonical_game_snapshot.dart';

/// Public, deterministic display changes only. Random loot, DNA, hidden scores
/// and server-only outcomes must never be generated by this client.
CanonicalGameSnapshot? predictGameDisplay(CanonicalGameSnapshot confirmed,
    String action, Map<String, dynamic> payload, DateTime now,
    {CanonicalGameSnapshot? preceding}) {
  if (confirmed.isSpeculative) return null;
  // Rebase a sequence of display-only predictions through the same public
  // schema. Only the returned, marked preview leaves this helper.
  if (preceding != null) {
    confirmed = CanonicalGameSnapshot.parse(
        {...confirmed.toJson(), 'data': preceding.data},
        expectedOwner: confirmed.ownerId,
        expectedAuthority:
            CanonicalGameAuthority.values.byName(confirmed.authorityMode));
  }
  final data = jsonDecode(jsonEncode(confirmed.data)) as Map<String, dynamic>;
  final collection = data['collection'] as Map<String, dynamic>;
  final inventory = data['inventory'] as Map<String, dynamic>;
  final wallet = data['wallet'] as Map<String, dynamic>;
  final dragons = (data['dragons'] as List).cast<Map<String, dynamic>>();
  final eggs = (data['eggs'] as List).cast<Map<String, dynamic>>();
  bool spend(String currency, int price) {
    if ((wallet[currency] as int) < price) return false;
    wallet[currency] = (wallet[currency] as int) - price;
    return true;
  }

  try {
    switch (action) {
      case 'refresh':
        // Time-based refills are still decided and committed by the server.
        // Keeping the last confirmed public view as a preview lets the
        // scheduled command use the durable optimistic queue without briefly
        // disabling otherwise unrelated gameplay.
        return confirmed.preview(data);
      case 'set_preferences':
        final changes = AccountPreferences.validateChanges(
            Map<String, dynamic>.from(
                jsonDecode(payload['changes'] as String)));
        (collection['preferences'] as Map).addAll(changes);
      case 'set_account_name':
        collection['accountName'] = payload['name'];
      case 'select_portrait':
      case 'select_title':
      case 'select_badge':
      case 'select_frame':
        final kind = action.substring('select_'.length);
        final capitalized = '${kind[0].toUpperCase()}${kind.substring(1)}';
        final id = payload['catalogId'];
        if (id != null &&
            !(collection['owned${capitalized}Ids'] as List).contains(id)) {
          return null;
        }
        collection['selected${capitalized}Id'] = id;
      case 'complete_tutorial':
        collection['tutorialCompleted'] = true;
      case 'call_dragon_to_floor':
        final house = data['house'] as Map;
        final rooms = house['towerFloorRoomIds'] as List;
        final index = payload['index'] as int;
        final roomId = payload['roomId'] as String;
        if (index < 0 ||
            index >= rooms.length ||
            rooms[index] != roomId ||
            (house['damagedTowerFloors'] as List).contains(index)) {
          return null;
        }
        final dragon = dragons
                .where(
                    (d) => d['location'] != 'released' && d['favorite'] == true)
                .firstOrNull ??
            dragons.where((d) => d['id'] == data['activeDragonId']).firstOrNull;
        if (dragon == null ||
            dragon['roamsTower'] != true ||
            dragon['activeAdventureId'] != null ||
            dragon['currentFloorIndex'] == index) {
          return null;
        }
        final returningVisitors = house['returningVisitors'] as Map;
        final occupancy = dragons.where((candidate) {
          final visitorUntil = returningVisitors[candidate['id']];
          final activeVisitor = candidate['location'] == 'released' &&
              visitorUntil is String &&
              DateTime.parse(visitorUntil).isAfter(now);
          return candidate['id'] != dragon['id'] &&
              candidate['currentFloorIndex'] == index &&
              ((candidate['location'] != 'released' &&
                      candidate['roamsTower'] == true) ||
                  activeVisitor);
        });
        if (occupancy.length >= towerFloorDragonCapacity) return null;
        dragon['currentFloorIndex'] = index;
        dragon['currentRoomId'] = roomId;
      case 'change_tower_floor_room':
        final house = data['house'] as Map;
        final rooms = house['towerFloorRoomIds'] as List;
        final index = payload['index'] as int;
        final room = houseRoomById(payload['roomId'] as String);
        if (index < 0 ||
            index >= rooms.length ||
            room == null ||
            room.id == 'nest') {
          return null;
        }
        rooms[index] = room.id;
        final unlocked = house['unlockedRoomIds'] as List;
        if (!unlocked.contains(room.id)) unlocked.add(room.id);
        for (final dragon in dragons) {
          if (dragon['currentFloorIndex'] == index) {
            dragon['currentRoomId'] = room.id;
          }
        }
      case 'abort_adventure':
        final runs = data['adventures']['runs'] as List;
        final run = runs.where((r) => r['id'] == payload['runId']).firstOrNull;
        if (run == null) return null;
        final definition = AdventureCatalog.byId[run['adventureId']];
        if (run['status'] != 'running' ||
            definition == null ||
            definition.kind == AdventureKind.group ||
            definition.requiresOnlinePartner ||
            !DateTime.parse(run['endsAt'] as String).isAfter(now)) {
          return null;
        }
        runs.remove(run);
        for (final dragon in dragons) {
          if (dragon['activeAdventureId'] == run['id']) {
            dragon['activeAdventureId'] = null;
          }
        }
      case 'reorder_tower_floor':
        final house = data['house'] as Map;
        final rooms = house['towerFloorRoomIds'] as List;
        final oldIndex = payload['oldIndex'] as int;
        final newIndex = payload['newIndex'] as int;
        if (oldIndex < 0 ||
            newIndex < 0 ||
            oldIndex >= rooms.length ||
            newIndex >= rooms.length) {
          return null;
        }
        final order = List.generate(rooms.length, (i) => rooms.length - i - 1);
        order.insert(newIndex, order.removeAt(oldIndex));
        final bottomOrder = order.reversed.toList();
        final indices = {
          for (var i = 0; i < bottomOrder.length; i++) bottomOrder[i]: i
        };
        house['towerFloorRoomIds'] = [for (final i in bottomOrder) rooms[i]];
        house['damagedTowerFloors'] = [
          for (final i in house['damagedTowerFloors'] as List) indices[i]
        ];
        house['damagedTowerRepairFactors'] = {
          for (final entry
              in (house['damagedTowerRepairFactors'] as Map).entries)
            '${indices[int.parse(entry.key as String)]}': entry.value
        };
        for (final dragon in dragons) {
          dragon['currentFloorIndex'] = indices[dragon['currentFloorIndex']] ??
              dragon['currentFloorIndex'];
        }
      case 'name_dragon':
        final dragon =
            dragons.where((d) => d['id'] == payload['dragonId']).firstOrNull;
        if (dragon == null) return null;
        dragon['name'] = payload['name'];
      case 'set_favorite_dragon':
        if (!dragons.any((d) => d['id'] == payload['dragonId'])) return null;
        for (final dragon in dragons) {
          dragon['favorite'] = dragon['id'] == payload['dragonId'];
        }
      case 'set_dragon_highlight':
        final dragon =
            dragons.where((d) => d['id'] == payload['dragonId']).firstOrNull;
        if (dragon == null) return null;
        final highlights = dragon['highlightedExpertises'] as List;
        highlights.remove(payload['focus']);
        if (payload['highlighted'] == true) highlights.add(payload['focus']);
      case 'tag_egg':
        final egg = eggs.where((e) => e['id'] == payload['eggId']).firstOrNull;
        if (egg == null) return null;
        egg['tagged'] = payload['tagged'];
        if (egg['returnBlockReason'] == null && payload['tagged'] == true) {
          egg['returnBlockReason'] = 'egg_tagged';
        } else if (egg['returnBlockReason'] == 'egg_tagged' &&
            payload['tagged'] == false) {
          egg['returnBlockReason'] = null;
        }
      case 'activate_egg':
        if (confirmed.nest != null) return null;
        final egg = eggs.where((e) => e['id'] == payload['eggId']).firstOrNull;
        if (egg == null ||
            egg['location'] != 'stash' ||
            (inventory['reservedOnlineTradeEggIds'] as List)
                .contains(egg['id'])) {
          return null;
        }
        egg['location'] = 'nest';
        egg['startedAt'] = now.toUtc().toIso8601String();
        egg['returnBlockReason'] = 'egg_in_nest';
      case 'start_adventure':
        final adventureId = payload['adventureId'] as String;
        final dragonId = payload['dragonId'] as String;
        final definition = AdventureCatalog.byId[adventureId];
        final dragon = dragons.where((d) => d['id'] == dragonId).firstOrNull;
        if (definition == null ||
            dragon == null ||
            dragon['location'] == 'released' ||
            dragon['stage'] == 'egg' ||
            dragon['activeAdventureId'] != null ||
            definition.kind == AdventureKind.group ||
            definition.requiresOnlinePartner ||
            definition.seasonalSpecial) {
          return null;
        }
        final adventures = data['adventures'] as Map<String, dynamic>;
        final options = adventures['adventureOptionIds'] as Map;
        final offered = options[definition.kind.name] as List?;
        if (offered == null || !offered.contains(adventureId)) return null;
        final training = dragon['training'] as Map;
        int score(TrainingFocus focus) => training[focus.name] as int? ?? 0;
        final duration = expertiseAdjustedAdventureDurationFromScores(
          definition,
          [score(definition.focus)],
          combinedExpertise:
              TrainingFocus.values.fold(0, (sum, focus) => sum + score(focus)),
        );
        final runId = 'pending-adventure-$dragonId';
        (adventures['runs'] as List).add({
          'id': runId,
          'adventureId': adventureId,
          'dragonId': dragonId,
          'startedAt': now.toUtc().toIso8601String(),
          'endsAt': now.add(duration).toUtc().toIso8601String(),
          'status': AdventureRunStatus.running.name,
          'participantCount': 1,
          'retraining': definition.expertiseCost > 0,
          'specialEventId': null,
          'specialEventKey': null,
          'rewardTier': null,
        });
        offered.remove(adventureId);
        dragon['activeAdventureId'] = runId;
      case 'claim_adventure':
        final adventures = data['adventures'] as Map<String, dynamic>;
        final runs = adventures['runs'] as List;
        final run = runs.where((r) => r['id'] == payload['runId']).firstOrNull;
        if (run == null ||
            AdventureCatalog.byId[run['adventureId']] == null ||
            (run['status'] != AdventureRunStatus.rewardReady.name &&
                DateTime.parse(run['endsAt'] as String).isAfter(now))) {
          return null;
        }
        runs.remove(run);
        final dragon =
            dragons.where((d) => d['id'] == run['dragonId']).firstOrNull;
        if (dragon == null || dragon['activeAdventureId'] != run['id']) {
          return null;
        }
        dragon['activeAdventureId'] = null;
      case 'purchase_portrait_chest':
      case 'purchase_title_chest':
      case 'purchase_music_chest':
        final (tier, currency, price) = switch (action) {
          'purchase_portrait_chest' => (
              'portrait',
              'gems',
              portraitChestGemPrice
            ),
          'purchase_title_chest' => ('title', 'coins', titleChestCoinPrice),
          _ => ('music', 'gems', musicChestGemPrice),
        };
        final capacity = switch (tier) {
          'portrait' => profilePortraitCatalog
              .where((p) => !confirmed.shop.portraits.contains(p.id))
              .length,
          'title' => accountTitleCatalog
              .where((p) => !confirmed.shop.titles.contains(p.id))
              .length,
          _ => musicCatalog.length - confirmed.shop.music.length,
        };
        if ((confirmed.shop.chests[tier] ?? 0) >= capacity) return null;
        if (!spend(currency, price)) return null;
        final stock = inventory['chestInventory'] as Map;
        stock[tier] = (stock[tier] as int? ?? 0) + 1;
      case 'purchase_furniture':
        final item = shopItemById(payload['catalogId'] as String);
        final owned = data['house']['ownedItemIds'] as List;
        if (item == null ||
            owned.contains(item.id) ||
            !spend(item.currency.name, item.price)) {
          return null;
        }
        owned.add(item.id);
      case 'craft_altar_relic':
        final relic = AltarRelic.values.byName(payload['relic'] as String);
        final altar = inventory['altar'] as Map;
        final materials =
            WeaveWallet.fromJson(Map<String, dynamic>.from(altar['wallet']));
        if (!materials.covers(relic.cost)) return null;
        altar['wallet'] = (materials - relic.cost).toJson();
        final stock = altar['crafted'] as Map;
        stock[relic.name] = (stock[relic.name] as int? ?? 0) + 1;
      default:
        return null;
    }
    return confirmed.preview(data);
  } on Object {
    // A future schema/rules change can disable a prediction, never the action.
    return null;
  }
}
